class MyClass:
    def __init__(self, x=CustomParam(1)):
        self.x = x

def test_custom_param_eq():
    obj = MyClass()
    # If the bug exists, param.default == param.empty will be True because CustomParam.__eq__ returns True.
    # Then it will yield just the value of self.x instead of (name, value, default).
    # Let's see what __rich_repr__ yields.
    results = list(obj.__rich_repr__())
    # Expected: ('x', CustomParam(1), CustomParam(1))
    # Actual (buggy): CustomParam(1)
    assert len(results) == 1
    assert isinstance(results[0], tuple)
    assert results[0][0] == 'x'

if __name__ == "__main__":
    try:
        test_custom_param_eq()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
